let wbBootCompleted=false,wbBootFailed=false;
function wbBootError(e){if(wbBootCompleted||e.type==='error'&&e.target!==window)return;wbBootFailed=true;const screen=document.getElementById('wbBootScreen');screen.setAttribute('role','alert');document.getElementById('wbBootMessage').textContent='起動に失敗しました。再読み込みしてください。';document.getElementById('wbBootReload').hidden=false}
