// Scope is part of the transient application plan. Saved form definitions and
// the existing atomic apply/Undo/storage contracts keep their original format.
const psClothingFields=new Set(['upper','lower','feet','head','hands','accessory','legwear']);
const psScopeNames={all:'両方',appearance:'衣装以外',clothing:'衣装のみ'};
function psValidScope(scope){afAssert(Object.hasOwn(psScopeNames,scope),'適用範囲が不正です');return scope}
function psFieldAllowed(field,scope){return scope==='all'||(field==='outfit'||field==='outfitExpandedFrom'||psClothingFields.has(field))===(scope==='clothing')}
function psPathAllowed(path,scope){
 if(scope==='all')return true;
 if(path[0]==='horror')return scope==='appearance';
 const field=['detail','detailCustom','itemWeights','itemColors'].includes(path[1])?path[2]:path[1];
 return psFieldAllowed(field,scope);
}
function psFilterSource(source,scope){
 source=cwCanonicalAppearance(source);
 if(scope==='all'||source?.captureVersion===1)return source;
 const next=afCopy(source);for(const field of ['hair','eyes','hairStyle','outfit','clearAppearance'])if(!psFieldAllowed(field,scope))delete next[field];
 if(next.detail)next.detail=Object.fromEntries(Object.entries(next.detail).filter(([field])=>psFieldAllowed(field,scope)));
 return next;
}
function psSpecificSource(source,scope){
 source=cwCanonicalAppearance(source);
 if(scope==='all')return source;
 const next=afCopy(source);for(const field of ['hair','eyes','eyesRight','eyeMode','hairStyle','outfit','horror'])if(!psFieldAllowed(field,scope))delete next[field];
 next.detail=Object.fromEntries(Object.entries(next.detail||{}).filter(([field])=>psFieldAllowed(field,scope)));return next;
}
function psScopedOwnership(ownership,scope){return !ownership||scope==='all'?ownership:{...ownership,entries:ownership.entries.filter(e=>psPathAllowed(e.path,scope))}}
function psMergeOwnership(previous,next,scope,formId){
 if(scope==='all')return next;
 const entries=[...(previous?.entries||[]).filter(e=>!psPathAllowed(e.path,scope)),...(next?.entries||[]).filter(e=>psPathAllowed(e.path,scope))];
 return entries.length?{version:1,formId,entries}:null;
}
function psProjectProfile(before,after,scope){
 const next=afCopy(after),restore=(parent,old,key)=>{if(Object.hasOwn(old||{},key))parent[key]=afCopy(old[key]);else delete parent[key]};
 for(const key of new Set([...Object.keys(before),...Object.keys(next)])){
  if(key==='characterPresetHistory')continue;
  if(['detail','detailCustom','itemWeights','itemColors'].includes(key)){
   for(const field of new Set([...Object.keys(before[key]||{}),...Object.keys(next[key]||{})]))if(!psFieldAllowed(field,scope)){next[key]??={};restore(next[key],before[key],field)}
   if(!Object.hasOwn(before,key)&&next[key]&&!Object.keys(next[key]).length)delete next[key];
  }else if(!psFieldAllowed(key,scope))restore(next,before,key);
 }
 return cwScopedLegacyAnatomy(before,next,scope);
}
function psFinishPlan(plan,scope){
 psValidScope(scope);if(scope==='all')return plan;
 afAssert(plan.ownerRef.kind==='person','この対象には適用範囲を分ける衣装がありません');
 plan.applicationScope=scope;plan.next=psProjectProfile(profiles[plan.actorRef.slice(7)]||{},plan.next,scope);
 if(scope==='clothing')plan.identity=afCopy(actorIdentityState(plan.actorRef)||{mode:'inherit',tokens:[]});
 plan.label+='（'+psScopeNames[scope]+'）';if(plan.next.characterPresetHistory)plan.next.characterPresetHistory.label=plan.label;
 plan.appearance=plan.appearance?.captureVersion===1?captureActorFormAppearance(plan.actorRef,plan.next):actorCurrentAppearance(plan.actorRef,plan.next);
 return plan;
}
function psApplyCaptured(ref,source,record,scope){
 source=cwCanonicalAppearance(source);record=cwCanonicalAppearance(record);
 if(scope==='all')return applyCapturedActorAppearance(ref,source,record);
 validateCapturedActorAppearance(source);const next=afCopy(record),existing=(field,value)=>{const row=catalog[field].find(x=>x.value===value);afAssert(row&&!maIsHidden('catalog:'+field,row.id),'必要な外見候補が未登録または非表示です：'+value);return row.id};
 if(scope==='appearance'){
  for(const [field,mode]of [['hairMode',source.hair.mode],['eyeMode',source.eyes.mode]])afAssert(structuralBuiltin[field].some(r=>r[0]===mode)&&!maIsHidden('structural:'+field,mode),'色モードが不正または非表示です');
  afAssert(source.hair.mode==='single'||source.hair.primary&&source.hair.secondary,'2色髪の色が不足しています');afAssert(source.eyes.mode!=='odd'||source.eyes.left&&source.eyes.right,'左右の目色が不足しています');
  for(const [key,field,value]of [['hairPrimary','hairColor',source.hair.primary],['hairSecondary','hairColor',source.hair.secondary],['eyeLeft','eyeColor',source.eyes.left],['eyeRight','eyeColor',source.eyes.right]])next[key]=value?existing(field,value):'';
  next.hairColor=next.hairPrimary;next.hairMode=source.hair.mode;next.eyeColor=next.eyeLeft;next.eyeMode=source.eyes.mode;next.hairStyle=source.hairStyle.map(v=>existing('hairStyle',v));next.colorWeights=afCopy(source.weights?.colorWeights||{});
 }else{
  next.outfit=source.outfit.map(v=>existing('outfit',v));
  for(const id of next.outfit)for(const [field,raw]of Object.entries(outfitSetForValue(item('outfit',id).value)||{})){const value=outfitDetailValue(field,raw);afAssert(detailOptions[field]?.options.some(r=>r[0]===value)&&!maIsHidden('detail:'+field,value),'衣装部位の候補が未登録または非表示です')}
  next.outfitExpandedFrom=item('outfit',asList(next.outfit).at(-1))?.value||'';
 }
 const fields=Object.entries(source.detail).filter(([field])=>psFieldAllowed(field,scope));
 next.detail??={};next.detailCustom??={};next.itemWeights??={};next.itemColors??={};
 for(const [field,values]of fields){for(const value of values)afAssert(detailOptions[field]?.options.some(r=>r[0]===value)&&!maIsHidden('detail:'+field,value),'必要な特徴候補が未登録または非表示です：'+value);next.detail[field]=values.slice();next.detailCustom[field]=source.detailCustom?.[field]||''}
 for(const field of [scope==='clothing'?'outfit':'hairStyle',...fields.map(([field])=>field)]){
  const values=['outfit','hairStyle'].includes(field)?source[field]:source.detail[field];
  for(const map of [source.weights?.itemWeights?.[field],source.weights?.itemColors?.[field]])for(const key of Object.keys(map||{}))afAssert(values.includes(key),'選択されていない外見の設定が含まれています');
  for(const shade of Object.values(source.weights?.itemColors?.[field]||{}))for(const color of Object.values(shade))afAssert(itemColorPalette.some(r=>r[0]===color),'外見部位の色が不正です');
  next.itemWeights[field]=afCopy(source.weights?.itemWeights?.[field]||{});next.itemColors[field]=afCopy(source.weights?.itemColors?.[field]||{});
 }
 return next;
}
function psFormHasClothing(ref,formId){
 const owner=actorOwnerForRef(ref),form=owner&&resolveActorForm(owner,formId);if(owner?.kind!=='person'||!form)return false;
 const source=cwCanonicalAppearance(actorFormLegacyPreset(form)||form.appearance);if(!source)return false;
 if(typeof source.outfit==='string'?!!source.outfit.trim():asList(source.outfit).length)return true;
 return [...psClothingFields].some(field=>asList(source.detail?.[field]).length||String(source.detailCustom?.[field]||'').trim());
}

