// Only explicitly reviewed built-in anatomy values are reclassified. Free text
// and user-defined values remain untouched, and normalization is a plan copy.
function cwBodySplit(field,value){return clothingData.bodyMoves.find(r=>r.field===field&&r.value===value)||null}
function cwCanonicalAppearance(source){
 if(!source||typeof source!=='object')return source;
 const next=afCopy(source);if(next.capture)next.capture=cwCanonicalAppearance(next.capture);
 for(const move of clothingData.bodyMoves){
  if(!asList(next.detail?.[move.field]).includes(move.value))continue;
  next.detail[move.field]=next.detail[move.field].flatMap(v=>v===move.value?move.clothing:v);
  next.detail.bodyFeatures=[...new Set([...asList(next.detail.bodyFeatures),...move.body])];
  const maps=next.captureVersion===1?next.weights:next;
  for(const key of ['itemWeights','itemColors']){
   const map=maps?.[key];if(!map?.[move.field]||!Object.hasOwn(map[move.field],move.value))continue;
   const setting=afCopy(map[move.field][move.value]);delete map[move.field][move.value];
   for(const v of move.clothing)map[move.field][v]??=afCopy(setting);
   map.bodyFeatures??={};for(const v of move.body)map.bodyFeatures[v]??=afCopy(setting);
  }
 }
 return next;
}
function cwScopedLegacyAnatomy(before,next,scope){
 if(scope==='all')return next;
 for(const field of ['head','hands','accessory']){
  const old=asList(before.detail?.[field]);if(!old.some(v=>cwBodySplit(field,v)))continue;
  next.detail??={};
  if(scope==='appearance'){
   next.detail[field]=old.flatMap(v=>cwBodySplit(field,v)?.clothing||[v]);
   for(const key of ['itemWeights','itemColors']){
    const map=next[key]?.[field];if(!map)continue;
    for(const value of old){const move=cwBodySplit(field,value);if(!move)continue;const setting=before[key]?.[field]?.[value];delete map[value];if(setting!==undefined)for(const v of move.clothing)map[v]=afCopy(setting)}
   }
  }else{
   const physical=old.flatMap(v=>cwBodySplit(field,v)?.body||[]);
   next.detail[field]=[...new Set([...asList(next.detail[field]),...physical])];
   for(const key of ['itemWeights','itemColors'])for(const value of old){
    const move=cwBodySplit(field,value),setting=before[key]?.[field]?.[value];if(!move||setting===undefined)continue;
    next[key]??={};next[key][field]??={};for(const v of move.body)next[key][field][v]=afCopy(setting);
   }
  }
 }
 return next;
}
function cwRegisterCatalog(){
 for(const row of clothingData.outfits)if(!catalog.outfit.some(r=>r.id===row.id||r.value===row.value))catalog.outfit.push({id:row.id,name:row.name,value:row.value,group:'キャラクター代表衣装'});
}
function cwRegisterParts(){
 for(const row of clothingData.outfits){
  outfitSets[row.value]??={...row.parts};
  for(const [field,value]of Object.entries(row.parts)){
   const label=row.partNames[field];outfitPartNames[value]??=label;
   if(!detailOptions[field].options.some(r=>r[0]===value))detailOptions[field].options.push([value,label,'キャラクター代表衣装']);
  }
 }
 for(const move of clothingData.bodyMoves){
  for(const value of move.body)if(!detailOptions.bodyFeatures.options.some(r=>r[0]===value))detailOptions.bodyFeatures.options.push([value,move.bodyName||value,'キャラクターの身体的特徴']);
  for(const value of move.clothing)if(!detailOptions[move.field].options.some(r=>r[0]===value))detailOptions[move.field].options.push([value,move.clothingName||value,'キャラクター代表衣装']);
 }
}
function cwCompletePresets(){
 for(const row of clothingData.outfits){
  for(const owner of row.owners){
   const key=Object.keys(characterBasicPresets).find(k=>k.normalize('NFKC').toLowerCase()===owner.normalize('NFKC').toLowerCase());
   if(!key)throw Error('衣装に対応する基本設定がありません：'+owner);
   for(const preset of characterBasicPresets[key])if(!preset.outfit){
    preset.outfit=row.value;
    // The legacy basic-preset resolver accepts six garment slots. Legwear is
    // expanded by the existing outfit-set path, rather than that resolver.
    preset.detail={...Object.fromEntries(Object.entries(row.parts).filter(([field])=>field!=='legwear').map(([field,value])=>[field,[value]])),...preset.detail};
   }
  }
 }
 for(const [owner,forms]of Object.entries(characterBasicPresets))characterBasicPresets[owner]=forms.map(cwCanonicalAppearance);
 for(const form of personSpecificDefinitions.forms){const next=cwCanonicalAppearance(form);if(next.detail)form.detail=next.detail}
 actorStandardForms=null;
}
// Translate ownership on legacy garment slots before restoring a specific form.
// Restore against the raw snapshots first, so a user's later edits are respected.
function cwPrepareOwnershipRoot(raw,ownership){
 const current={...raw,profile:cwCanonicalAppearance(raw.profile)};
 const needs=ownership?.entries?.some(e=>e.path[0]==='profile'&&e.path[1]==='detail'&&
  ['head','hands','accessory'].includes(e.path[2])&&
  [e.before,e.after].some(s=>s?.exists&&asList(s.value).some(v=>cwBodySplit(e.path[2],v))));
 if(!needs)return {root:current,ownership};
 const restored=afCopy(raw);ufRestoreOwned(restored,ownership);restored.profile=cwCanonicalAppearance(restored.profile);
 const paths=[...ownership.entries.map(e=>e.path),['profile','detail','bodyFeatures']];
 const unique=new Map(paths.map(p=>[JSON.stringify(p),p])),entries=[];
 for(const path of unique.values()){
  const before=ufSnapshot(restored,path),after=ufSnapshot(current,path);
  if(!hEqual(before,after))entries.push({path,before,after});
 }
 return {root:current,ownership:{...ownership,entries}};
}
// Saved catalog metadata from older versions may still use the old VSPO group.
// Ownership is attached to these known definitions, independent of that label.
let cwOwnerIndex=null;
function cwKnownCandidateOwners(source,value){
 if(source!=='catalog:outfit'||/^custom-|^ma-|^restored-/.test(value))return null;
 const row=item('outfit',value);if(!row)return null;
 if(!cwOwnerIndex){
  cwOwnerIndex=new Map();
  const add=(key,owners)=>{const set=cwOwnerIndex.get(key)||new Set();for(const owner of owners)set.add(owner);cwOwnerIndex.set(key,set)};
  for(const r of clothingData.outfits){add(r.id,r.owners);add(r.value,r.owners)}
  for(const m of vspoJPData.members){const owners=[m.roman+' (VSPO!)'];add('vspo-outfit-'+m.id.slice(15),owners);add(m.preset.outfit,owners)}
 }
 return cwOwnerIndex.get(value)||cwOwnerIndex.get(row.value)||null;
}
